SELECT COUNT(*) AS benchmark_count FROM benchmark_indices;
SELECT COUNT(*) AS daily_price_count FROM benchmark_daily_prices;
SELECT b.index_code,b.index_name,MIN(p.trade_date) first_date,MAX(p.trade_date) last_date,COUNT(p.id) rows_count
FROM benchmark_indices b LEFT JOIN benchmark_daily_prices p ON p.benchmark_id=b.benchmark_id
GROUP BY b.benchmark_id,b.index_code,b.index_name ORDER BY b.benchmark_id;
COMMIT;